{
  "mechanisms": [
    {
      "name": "asymmetric_learning_rates",
      "title": "Asymmetric Learning Rates",
      "description": "Separate learning rates are applied depending on whether the reward prediction error is positive or negative.",
      "params": [
        {
          "name": "alpha_pos",
          "bounds": [0, 1]
        },
        {
          "name": "alpha_neg",
          "bounds": [0, 1]
        }
      ],
      "evidence": "lr_1 = alpha_pos if delta_stage1 > 0 else alpha_neg\nq_stage1_mf[action_1[trial]] += lr_1 * delta_stage1\n\ndelta_stage2 = reward[trial] - q_stage2_mf[state_idx, action_2[trial]]\nlr_2 = alpha_pos if delta_stage2 > 0 else alpha_neg\nq_stage2_mf[state_idx, action_2[trial]] += lr_2 * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Stage 1 values are computed as a weighted average of model-based and model-free Q-values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "A perseverance bonus is added to the stage 1 logits for repeating the action chosen in the previous trial.",
      "params": [
        {
          "name": "p",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "rep = np.zeros(2)\nif last_action_1 != -1:\n    rep[last_action_1] = 1.0\nlogits_1 = beta * q_stage1_net + p * rep",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Stage 1 model-free Q-values are updated using the stage 2 reward prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lambda_",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += lr_2 * lambda_ * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "unchosen_value_decay",
      "title": "Unchosen Value Decay",
      "description": "Q-values for unchosen actions at both stages decay towards a neutral expected value of 0.5.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "for a in range(2):\n    if a != action_1[trial]:\n        q_stage1_mf[a] = (1 - decay) * q_stage1_mf[a] + decay * 0.5\nfor s in range(2):\n    for a in range(2):\n        if not (s == state_idx and a == action_2[trial]):\n            q_stage2_mf[s, a] = (1 - decay) * q_stage2_mf[s, a] + decay * 0.5",
      "expressible_in_slots": true
    }
  ]
}
